/**
 * @method
 * @name scwin.tx_fn_AnnouncementView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_AnnouncementView = async function () {
    const sbmOptions = {
        id: "tx_fn_AnnouncementView",
        method: "post",
        action: "/outer/announcement.do",
        ref: "dma_AnnouncementViewReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40200.tx_fn_AnnouncementView" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
