*/
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/outer/register.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40200.tx_fn_Confirm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.announcementView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.announcementView = async function () {
    /* sdd-asis-lifecycle:begin fn_AnnouncementView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.applyCheck || { elements: [] });
    $c.util.getComponent('dma_AnnouncementViewReq').set('method', 'searchAnnouncementDetail');
    $c.util.getComponent('dma_AnnouncementViewReq').set('contnId', '10004');
    frm.action = '/outer/announcement.do';
    await scwin.tx_fn_AnnouncementView();
    /* sdd-asis-lifecycle:end */
};


async function confirm() {
    /* sdd-asis-lifecycle:begin fn_Confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.applyCheck || { elements: [] });
    if (!$c.cm.fn_IsChecked($c.util.getComponent('rd_corpUsrTpCd'))) {
        await $c.win.alert('회원 분류를 선택하세요');
        return;
    }
    if (frm.isurCd) {
        if (frm.isurCd.value.length != 5) {
            await $c.win.alert('회사코드는 반드시 5자리를 입력하셔야 합니다');
            return;
        }
        $c.util.getComponent('dma_AnnouncementViewReq').set('uniqueCode', frm.isurCd.value);
    }
    if (frm.mbrNo) {
        $c.util.getComponent('dma_AnnouncementViewReq').set('uniqueCode', frm.mbrNo.value);
    }
    if ($c.cm.fn_NullChk(frm.uniqueCode)) {
        return;
    }
    if ($c.util.fieldEl('dma_ConfirmReq', 'corpUsrNm')) {
        if ($c.cm.fn_NullChk($c.util.getComponent('dma_ConfirmReq'))) {
            return;
        }
        if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('dma_ConfirmReq'))) {
            return;
        }
        $c.util.getComponent('dma_ConfirmReq').set('corpUsrNm', $c.cm.fn_IgnoreSpaces($c.util.getComponent('dma_ConfirmReq').get('corpUsrNm')));
    }
    $c.util.getComponent('dma_AnnouncementViewReq').set('method', 'registerApplyForm');
    frm.action = '/outer/register.do';
    await scwin.tx_fn_Confirm();
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.changeUsrTpCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.changeUsrTpCd = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_ChangeUsrTpCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const usrTpCd = _obj.getValue();
    if (usrTpCd === '14') {
        (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('2')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('2')) : void (scwin.getIsurCdTitle('2'))));
    } else {
        if (usrTpCd === '22') {
            (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('3')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('3')) : void (scwin.getIsurCdTitle('3'))));
        } else {
            if (usrTpCd === '15' || usrTpCd === '23') {
                (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('4')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('4')) : void (scwin.getIsurCdTitle('4'))));
            } else {
                (($c.util.getComponent("txt_isurCdDiv")) && ($c.util.getComponent("txt_isurCdDiv")).setValue ? ($c.util.getComponent("txt_isurCdDiv")).setValue(scwin.getIsurCdTitle('1')) : (($c.util.getComponent("txt_isurCdDiv")) ? (($c.util.getComponent("txt_isurCdDiv")).innerHTML = scwin.getIsurCdTitle('1')) : void (scwin.getIsurCdTitle('1'))));
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param _target
 * @returns
 * @hidden N
*/
scwin.goURL = function (_target) {
    /* sdd-asis-lifecycle:begin fn_GoURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let linkUrl;
    if (_target === 'registerInfo') {
        linkUrl = '/outer/register.do?method=registerInfo';
    } else {
        if (_target === 'faq') {
            linkUrl = '/outer/faq.do?method=searchFAQ&faqBzTpCd=5';
        }
    }
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkUrl));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
